1	/**
2	 * Main Cloudflare Worker entry point for the Paperclip API.
3	 *
4	 * This file:
5	 *   1. Creates a Hono app and mounts route definitions.
6	 *   2. Implements the first-run setup gate (redirects to /setup until KV flag is set).
7	 *   3. Handles Cloudflare Queues message batches (plugin job fanout).
8	 *   4. Handles Cloudflare Cron Triggers (heartbeat sweep, budget checks, DB backup).
9	 *   5. Re-exports all Durable Object and Workflow classes so Wrangler can
10	 *      register them — they must be named exports from the Worker's main module.
11	 */
12	
13	import { Hono } from "hono";
14	import { createSetupApp } from "./setup.js";
15	import { bootCloudflare } from "../boot.js";
16	import { SidecarClient } from "../sidecar-client.js";
17	import { CfCompanySkillsService } from "../services/cf-company-skills.js";
18	import { CfAgentInstructionsService } from "../services/cf-agent-instructions.js";
19	
20	// createHyperdriveDb is imported here to make it available for use when the
21	// HTTP adapter migration lands (PR #6/#7). Remove the comment and use it in
22	// the fetch handler once route modules are mounted.
23	// import { createHyperdriveDb } from "../db/hyperdrive.js";
24	
25	// ---------------------------------------------------------------------------
26	// Env — Cloudflare bindings injected at runtime
27	// ---------------------------------------------------------------------------
28	
29	export interface Env {
30	  // Databases
31	  HYPERDRIVE: { connectionString: string };
32	
33	  // Object storage
34	  PAPERCLIP_STORAGE: R2Bucket;
35	
36	  // KV — setup flags, hot config, session cache
37	  PAPERCLIP_KV: KVNamespace;
38	
39	  // Durable Object namespaces
40	  TASK_DO: DurableObjectNamespace;
41	  AGENT_RUN_DO: DurableObjectNamespace;
42	  SCHEDULER_DO: DurableObjectNamespace;
43	
44	  // Queues
45	  PAPERCLIP_QUEUE: Queue;
46	
47	  // Workflows
48	  HEARTBEAT_WORKFLOW: Workflow;
49	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
50	
51	  // Vars (set in wrangler.toml [vars])
52	  DEPLOYMENT_PLATFORM: string;
53	  DEPLOYMENT_MODE: string;
54	  DEPLOYMENT_EXPOSURE: string;
55	
56	  // Secrets (set via `wrangler secret put`)
57	  // MASTER_ENCRYPTION_KEY: string  — encrypts all other secrets stored in DB
58	  // SANDBOX_BRIDGE_URL: string
59	  // SANDBOX_BRIDGE_API_KEY: string
60	
61	  // Sidecar — the Node server running alongside the Workers deployment.
62	  // Workers delegate filesystem, child-process, and plugin-loading operations
63	  // to this process over HTTP (see SidecarClient).
64	  SIDECAR_URL: string;
65	  SIDECAR_API_KEY: string;
66	}
67	
68	// ---------------------------------------------------------------------------
69	// Hono app
70	// ---------------------------------------------------------------------------
71	
72	const app = new Hono<{ Bindings: Env }>();
73	
74	// Health check — always reachable, no auth, no setup gate
75	app.get("/api/health", (c) =>
76	  c.json({
77	    status: "ok",
78	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
79	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
80	    ts: new Date().toISOString(),
81	  }),
82	);
83	
84	// First-run setup gate — redirect to /setup until SETUP_COMPLETED is "true"
85	app.use("*", async (c, next) => {
86	  // Allow the setup routes and health check through unconditionally
87	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
88	    return next();
89	  }
90
